// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }
    function testFuzz_property(uint256 amount, uint256 t, uint256 am, address actor) public {
        vm.assume(actor != address(c) && actor != address(this) && actor.code.length == 0);
        amount = bound(amount, 1 ether, 1000 ether);
        t = bound(t, block.timestamp + 1, block.timestamp + 1e18);
        am = bound(am, 0, amount);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(t);
        vm.prank(actor);
        c.Collect(am);
        (, uint256 balAfter) = c.Acc(actor);
        assertTrue(balAfter == amount, "locked funds must remain untouched until unlockTime");
    }
}
